const todayIso = () => new Date().toISOString().slice(0, 10)
const parseDateIso = (value: string | undefined): string => {
  const raw = String(value || '').trim()
  if (!raw) return ''
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw
  if (/^\d{4}-\d{1,2}$/.test(raw)) return `${raw.slice(0, 4)}-${raw.slice(5).padStart(2, '0')}-01`
  let match = /^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/.exec(raw)
  if (match) return `${match[3]}-${match[2].padStart(2, '0')}-${match[1].padStart(2, '0')}`
  match = /^(\d{1,2})[\/-](\d{4})$/.exec(raw)
  if (match) return `${match[2]}-${match[1].padStart(2, '0')}-01`
  return raw
}
const dateBefore = (left: string | undefined, right: string | undefined) => { const a = parseDateIso(left); const b = parseDateIso(right); return Boolean(a && b && a > b) }
