const pendingCalvesFromReproduction = (): PendingCalf[] => {
  const reproduction = readReproductionState()
  const rows = reproduction.calvings
    .filter((calving) => calving.status === 'VALID')
    .flatMap((calving) => calving.calves.map((calf, index) => ({ calving, calf, index })))
    .filter(({ calf }) => calf.outcome === 'LIVE' && calf.registrationState === 'PENDING_CONFIRMATION')
    .map(({ calving, calf, index }) => {
      const check = reproduction.checks.find((item) => item.id === calving.pregnancyCheckId)
      const breeding = reproduction.events.find((item) => item.id === check?.linkedBreedingId)
      const sire = calf.sireCode || breeding?.sire || 'Không rõ'
      const conceptionSource = breeding?.method === 'AI'
        ? `Thụ tinh nhân tạo${breeding.semenBatch ? ` · tinh ${breeding.semenBatch}` : ''}`
        : breeding?.method === 'NATURAL' ? 'Phối tự nhiên' : 'Không rõ'
      return {
        id: calf.id,
        calf: `Bê ${calving.code} · ${index + 1}`,
        tag: calf.tag?.trim() || 'Chưa gắn thẻ',
        dam: calf.damCode || calving.code,
        sire,
        conceptionSource,
        sex: calf.sex === 'MALE' ? 'Đực' : calf.sex === 'FEMALE' ? 'Cái' : 'Chưa xác định',
        birth: calving.birthAt.slice(0, 10),
        weight: String(calf.birthWeight),
        weightBasis: calf.weightBasis === 'ESTIMATED' ? 'Estimated' as const : 'Measured' as const,
        breed: calf.breed || 'Chưa xác định',
      }
    })
  return rows.length ? rows : fallbackPendingCalves
}
const pendingRegistrationCalves = (): PendingCalf[] => {
  const registered = new Set(readDemo<string[]>('registered-pending-calf-ids', []))
  const legacy = readDemo<{ registered?: string[] }>('pending-calves', {})
  for (const id of legacy.registered || []) registered.add(id)
  return pendingCalvesFromReproduction().filter((calf) => !registered.has(calf.id))
}
const lineAmount = (line: Line, pricingBasis: 'Per kg' | 'Per head' = 'Per kg') => pricingBasis === 'Per head' ? Number(line.price || 0) : Number(line.weight || 0) * Number(line.price || 0)
const reviewLineError = (line: Line, pricingBasis: 'Per kg' | 'Per head', entryDate: string | undefined, criteriaIssues: string[]) => {
  if (pricingBasis === 'Per kg' && !line.weight) return 'Cân nhập (kg) là bắt buộc khi phiếu tính giá theo kg.'
  if (line.weight && (Number(line.weight) < 1 || Number(line.weight) > 1500)) return 'Cân nhập phải từ 1 đến 1.500 kg.'
  if (line.tag.length > 30 || line.name.length > 50) return 'Số tai phụ tối đa 30 ký tự; tên gọi tối đa 50 ký tự.'
  if (line.diseaseNote && line.diseaseNote.length > 1000) return 'Chi tiết bệnh tối đa 1.000 ký tự.'
  if (line.repro === 'Known' && (!line.earlierCalvings?.trim() || Number(line.earlierCalvings) < 0 || !line.pregnantAtEntry || (line.pregnantAtEntry === 'Có' && (!line.pregnantMonths?.trim() || Number(line.pregnantMonths) < 0)))) return 'Cần nhập số lứa trước, mang thai và số tháng nếu có.'
  if (line.reproNote && line.reproNote.length > 1000) return 'Chi tiết sinh sản tối đa 1.000 ký tự.'
  if (criteriaIssues.length && !line.warningReason?.trim()) return 'Chuồng chưa phù hợp tiêu chí; cần nhập lý do cảnh báo để tiếp tục.'
  if (entryDate && line.vaccineRows?.some((row) => row.date && dateBefore(row.date, entryDate))) return 'Ngày vaccine phải không muộn hơn ngày nhập.'
  return undefined
}
const ageMonths = (birth: string) => { const parsed = parseDateIso(birth); if (!parsed) return null; const date = new Date(`${parsed}T00:00:00`); if (Number.isNaN(date.getTime())) return null; const now = new Date(); return Math.max(0, (now.getFullYear() - date.getFullYear()) * 12 + (now.getMonth() - date.getMonth()) - (now.getDate() < date.getDate() ? 1 : 0)) }
const penCriteriaIssues = (line: Line, target: (typeof seedPens)[number] | undefined): string[] => { if (!target) return ['Chuồng đích không tồn tại.']; const issues: string[] = []; if (target.status !== 'ACTIVE') issues.push('Chuồng đích đang ngừng sử dụng.'); if (target.count >= target.capacity) issues.push(`Chuồng đích đã đầy (${target.count}/${target.capacity}).`); if (target.stage !== 'Mọi giai đoạn' && target.stage !== line.stage) issues.push(`Giai đoạn ${line.stage || 'chưa xác định'} không khớp tiêu chí ${target.stage}.`); if (target.purpose !== 'Mọi mục đích' && target.purpose !== line.purpose) issues.push(`Mục đích ${line.purpose || 'chưa xác định'} không khớp tiêu chí ${target.purpose}.`); if (target.sex !== 'Cả hai' && target.sex !== line.sex) issues.push(`Giới tính ${line.sex || 'chưa xác định'} không khớp tiêu chí ${target.sex}.`); const age = ageMonths(line.birth); if (target.minAge != null && age != null && age < target.minAge) issues.push(`Tuổi ${age} tháng thấp hơn ngưỡng ${target.minAge} tháng.`); if (target.minWeight != null && line.weight && Number(line.weight) < target.minWeight) issues.push(`Cân ${line.weight} kg thấp hơn ngưỡng ${target.minWeight} kg.`); return issues }
