  const navigate = useNavigate(); const readOnly = state === 'read-only'; const pendingCalfCount = pendingRegistrationCalves().length; const [rows, setRows] = useState(() => expandLocalTable('entry-vouchers', readDemo<Voucher[]>('entry-vouchers', seedVouchers))); const [tab, setTab] = useState('ALL'); const [fromDate, setFromDate] = useState(''); const [toDate, setToDate] = useState(''); const [typeFilter, setTypeFilter] = useState('ALL'); const [sourceFilter, setSourceFilter] = useState('ALL'); const sources = [...new Set(rows.map((row) => row.source).filter(Boolean))]; const visible = rows.filter((row) => (tab === 'ALL' || row.status === tab) && (typeFilter === 'ALL' || row.type === typeFilter) && (sourceFilter === 'ALL' || row.source === sourceFilter) && (!fromDate || parseDateIso(row.date) >= fromDate) && (!toDate || parseDateIso(row.date) <= toDate)); const postedRows = rows.filter((row) => row.status === 'POSTED'); const selectVoucher = (row: Voucher) => { writeDemo('selected-voucher', { code: row.code }); navigate(`${row.status === 'DRAFT' ? (row.type === 'Bê sinh tại trại' ? '/ui/scr-36' : '/ui/scr-34') : '/ui/scr-106'}?id=${encodeURIComponent(row.code)}`) }
